import{_ as t,o as a,c as r,a7 as s}from"./chunks/framework.BJyR0VjM.js";const u=JSON.parse('{"title":"Auto-Restart","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/auto-restart.md","filePath":"documentation/auto-restart.md"}'),o={name:"documentation/auto-restart.md"};function i(n,e,l,h,c,d){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="auto-restart" tabindex="-1">Auto-Restart <a class="header-anchor" href="#auto-restart" aria-label="Permalink to “Auto-Restart”">​</a></h1><p>YggUtils automatically restarts your Minecraft server if it exits unexpectedly, without any extra configuration.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to “How It Works”">​</a></h2><p>After the server process exits, YggUtils checks the exit code:</p><ul><li><strong>Exit code <code>0</code></strong> — the server shut down cleanly (e.g. someone ran <code>/stop</code>). YggUtils exits too.</li><li><strong>Any other exit code</strong> — the server crashed or was killed unexpectedly. YggUtils waits <strong>3 seconds</strong> and relaunches it.</li></ul><p>This restart loop runs indefinitely until a clean shutdown happens.</p><h2 id="clean-shutdown" tabindex="-1">Clean Shutdown <a class="header-anchor" href="#clean-shutdown" aria-label="Permalink to “Clean Shutdown”">​</a></h2><p>To stop both the server and YggUtils together, shut down the server normally from within Minecraft:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/stop</span></span></code></pre></div><p>Or type <code>stop</code> directly in the console. YggUtils forwards this to the server, the server exits with code <code>0</code>, and the wrapper exits as well.</p><h2 id="crash-scenario" tabindex="-1">Crash Scenario <a class="header-anchor" href="#crash-scenario" aria-label="Permalink to “Crash Scenario”">​</a></h2><p>If the server crashes (OutOfMemoryError, plugin exception that kills the JVM, etc.), YggUtils will:</p><ol><li>Detect the non-zero exit</li><li>Wait 3 seconds</li><li>Re-run the same launch command</li><li>Resume piping output and forwarding console input</li></ol><h2 id="killing-yggutils-directly" tabindex="-1">Killing YggUtils Directly <a class="header-anchor" href="#killing-yggutils-directly" aria-label="Permalink to “Killing YggUtils Directly”">​</a></h2><p>If you kill the YggUtils process (e.g. <code>Ctrl+C</code>, <code>SIGTERM</code>, or a hosting panel &quot;stop&quot; that targets the wrapper), the child server process may continue running as an orphan depending on your OS and how the signal is handled.</p><p>For clean shutdown in production environments, always use <code>/stop</code> from within the server rather than terminating the wrapper process externally.</p>',16)])])}const g=t(o,[["render",i]]);export{u as __pageData,g as default};
